import XCTest
@testable import SecureTestCore

/// Row DC (docs/graphing-calculator-design.md D-3): the vendored calculator
/// literal, `graphingScript`, generated by packages/graphing/scripts/
/// build-page.ts. Our own page code keeps its no-HTML-APIs posture
/// (`rendererScriptWithoutVendored`); this pins what the vendored part is
/// allowed to be.
final class GraphingScriptTests: XCTestCase {
    let script = AssessmentPage.graphingScript

    func testItIsOneDormantFunctionAfterTheNotices() {
        // Nothing runs at page load: the literal defines one function and
        // has no statement outside it.
        let body = script.components(separatedBy: "\nfunction __secureTestGraphing() {\n")
        XCTAssertEqual(body.count, 2)
        XCTAssertTrue(body[0].hasPrefix("/*! SecureTest graphing calculator"))
        XCTAssertTrue(body[1].hasSuffix("  return __gcOut;\n}"))
        XCTAssertFalse(body[0].contains("function"))
    }

    func testLicenceNoticesTravelWithTheCode() {
        XCTAssertTrue(script.contains("MIT License"))
        XCTAssertTrue(script.contains("MathLive 0.111.1"))
        XCTAssertTrue(script.contains("Arno Gourdol"), "MathLive's copyright line")
    }

    func testNothingCanEndOrConfuseTheInlineScriptElement() {
        XCTAssertFalse(script.contains("</"))
        XCTAssertFalse(script.contains("<!--"))
        XCTAssertFalse(script.lowercased().contains("<script"))
    }

    func testNoEvalAndNoNetworkBeyondWhatTheCSPRefuses() {
        // The CSP has no unsafe-eval and no connect-src; MathLive's sound and
        // font loaders are switched off in configureMathLive, and would be
        // refused by the CSP anyway. Pinned so a bump that adds one is seen.
        XCTAssertFalse(script.contains("new Function"))
        XCTAssertFalse(script.contains("eval("))
        XCTAssertFalse(script.contains("XMLHttpRequest"))
        XCTAssertFalse(script.contains("WebSocket"))
        XCTAssertFalse(script.contains("localStorage"))
    }

    /// Our own page code is guarded by `rendererScriptWithoutVendored`; the
    /// vendored part (all from MathLive — packages/graphing/src has no HTML
    /// APIs) keeps its HTML sinks to this exact set, so a MathLive bump that adds
    /// one fails here and gets read (PR #86 review). The 22 `innerHTML =` sites
    /// write MathLive's own markup — rendered LaTeX, keyboard plates, menus,
    /// its stylesheet — and authored LaTeX is escaped on the way: on 2026-10-24
    /// a field given `\text{<img onerror=…>}`, `x_{<svg onload=…>}` and three
    /// more produced no element and ran nothing. The page CSP allows inline
    /// script (`unsafe-inline`), so this escaping is the wall that matters.
    func testItsHTMLSinksArePinned() {
        func count(_ pattern: String) -> Int {
            let re = try! NSRegularExpression(pattern: pattern)
            return re.numberOfMatches(in: script, range: NSRange(script.startIndex..., in: script))
        }
        XCTAssertEqual(count(#"\.innerHTML\s*="#), 22, "an innerHTML site was added or removed: read it, then update this count")
        XCTAssertEqual(count(#"\.innerHTML\s*\+="#), 0)
        XCTAssertEqual(count(#"outerHTML\s*="#), 0)
        XCTAssertEqual(count("insertAdjacentHTML"), 0)
        XCTAssertEqual(count(#"document\.write"#), 0)
    }

    func testThePageSplicesItOnceAndOursStaysSeparable() {
        let page = AssessmentPage.rendererScript
        XCTAssertEqual(page.components(separatedBy: script).count, 2)
        XCTAssertFalse(AssessmentPage.rendererScriptWithoutVendored.contains("__gcOut"))
    }
}
